package net.rossonet.waldot.cli.commands;

import java.util.concurrent.Callable;

import picocli.AutoComplete;
import picocli.CommandLine.Command;
import picocli.CommandLine.Model.CommandSpec;
import picocli.CommandLine.Spec;

/**
 * {@code wotctl completion}: script of the shell completion (bash and zsh),
 * generated by picocli from the model of the commands.
 */
@Command(name = "completion", header = "Script di autocompletamento per bash e zsh.", mixinStandardHelpOptions = true, description = {
		"Scrive su stdout lo script di autocompletamento di wotctl per bash (funziona anche",
		"in zsh con bashcompinit). Completa comandi, sottocomandi, opzioni, i valori delle",
		"opzioni con un insieme fisso di valori (es. --security-policy, -o, --type) e i",
		"nomi dei file. Non si collega al server.", "",
		"Lo script cerca il comando 'wotctl' nel PATH: con un alias (es. java -jar) il",
		"completamento funziona comunque, perché è associato al nome 'wotctl'."}, footer = {
				"Esempi:", "  # solo nella shell corrente",
				"  source <(wotctl completion)", "",
				"  # per tutti gli utenti (bash)",
				"  wotctl completion | sudo tee /etc/bash_completion.d/wotctl >/dev/null",
				"", "  # per l'utente corrente (bash)",
				"  mkdir -p ~/.local/share/bash-completion/completions",
				"  wotctl completion > ~/.local/share/bash-completion/completions/wotctl",
				"", "  # zsh (in ~/.zshrc)",
				"  autoload -U +X compinit && compinit",
				"  autoload -U +X bashcompinit && bashcompinit",
				"  source <(wotctl completion)"})
public class CompletionCommand implements Callable<Integer> {

	@Spec
	private CommandSpec spec;

	@Override
	public Integer call() {
		spec.commandLine().getOut().print(AutoComplete.bash(
				spec.root().name(), spec.root().commandLine()));
		spec.commandLine().getOut().flush();
		return 0;
	}
}
